#include <fstream>              // header for all file streams

ofstream out("data.txt");       // open for writing (old content erased)
if (!out) {                     // check: did it open?
    cout << "Error opening file!" << endl;
    return 1;
}
out << "text" << 42 << endl;    // write, exactly like cout
out.close();                    // close when finished

ifstream in("data.txt");        // open for reading
if (!in) { cout << "File not found!" << endl; return 1; }
string line;
getline(in, line);              // read one line
in.close();

ofstream more("data.txt", ios::app);   // append: keep old content
fstream both;                          // can read and write

sample.code:
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ofstream out("hello.txt");
    if (!out) {
        cout << "Cannot open hello.txt" << endl;
        return 1;
    }
    out << "Hello, file!" << endl;
    out.close();

    ifstream in("hello.txt");
    if (!in) {
        cout << "Cannot open hello.txt" << endl;
        return 1;
    }
    string line;
    getline(in, line);
    in.close();
    cout << "Read back: " << line << endl;
    return 0;
}

#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ifstream first("notes.txt");
    if (!first) {
        cout << "notes.txt does not exist yet" << endl;
    }

    ofstream make("notes.txt");
    make << "Week 14: files" << endl;
    make.close();

    ifstream second("notes.txt");
    if (second) {
        string line;
        getline(second, line);
        cout << "Now it exists: " << line << endl;
    }
    second.close();
    return 0;
}

#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ofstream out("names.txt");
    if (!out) {
        cout << "Cannot open names.txt" << endl;
        return 1;
    }
    out << "Ali" << endl;
    out.close();

    ofstream more("names.txt", ios::app);
    if (!more) {
        cout << "Cannot open names.txt" << endl;
        return 1;
    }
    more << "Sana" << endl;
    more.close();

    ifstream in("names.txt");
    if (!in) {
        cout << "Cannot open names.txt" << endl;
        return 1;
    }
    string line;
    int count = 0;
    while (getline(in, line)) {
        count++;
        cout << count << ": " << line << endl;
    }
    in.close();
    return 0;
}

